effect.shader:
float gmLum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec2 px = 1.0 / getTexSize(inputImg.size);
float l0 = gmLum(texture2DCv(inputImg.texture, uv).rgb);
float lx = gmLum(texture2DCv(inputImg.texture, clamp(uv + vec2(px.x, 0.0), 0.0, 1.0)).rgb)
- gmLum(texture2DCv(inputImg.texture, clamp(uv - vec2(px.x, 0.0), 0.0, 1.0)).rgb);
float ly = gmLum(texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, px.y), 0.0, 1.0)).rgb)
- gmLum(texture2DCv(inputImg.texture, clamp(uv - vec2(0.0, px.y), 0.0, 1.0)).rgb);
float edge = clamp(length(vec2(lx, ly)) * lineGain / max(lineThresh, 0.01), 0.0, 1.0);
edge = smoothstep(0.25, 0.9, edge);
vec3 col = paperCol.rgb;
vec2 gsz = getTexSize(inputImg.size);
float g1 = step(0.94, fract(uv.x * gsz.x / 32.0)) + step(0.94, fract(uv.y * gsz.y / 32.0));
float g2 = step(0.96, fract(uv.x * gsz.x / 8.0)) + step(0.96, fract(uv.y * gsz.y / 8.0));
col += vec3(0.20, 0.32, 0.45) * clamp(g1, 0.0, 1.0) * gridStrength * 0.6;
col += vec3(0.12, 0.22, 0.33) * clamp(g2, 0.0, 1.0) * gridStrength * 0.35;
float l = gmLum(src.rgb);
col = mix(col, col * (0.75 + 0.5 * l), paperPhoto);
col = mix(col, lineCol.rgb, edge);
col *= 1.0 - paperVig * 0.8 * smoothstep(0.3, 0.85, length(uv - 0.5));
gl_FragColor = vec4(col * src.a, src.a);
}
